import { useState, useRef, useEffect, useCallback } from 'react'
import { useDispatch } from 'react-redux'
import type { TunerConfig, PitchEvent, InstrumentDefinition, TuningDefinition } from '../types'
import { useMedia } from '../../shared/hooks/useMedia'
import { freqToMidi, midiToFreq, midiToNoteName, centsDifference } from '../utils/pitchUtils'
import { setPitchEvent, clearPitchEvent, setListening as setListeningAction } from '../store/tunerSlice'

export function useTuner(initialConfig?: Partial<TunerConfig>) {
  const dispatch = useDispatch()
  const media = useMedia({ audio: true })
  const [isListening, setListening] = useState(false)
  const [lastPitch, setLastPitch] = useState<PitchEvent | undefined>(undefined)
  const [selectedInstrument, setSelectedInstrument] = useState<InstrumentDefinition | null>(null)
  const [selectedTuning, setSelectedTuning] = useState<TuningDefinition | null>(null)
  const configRef = useRef<TunerConfig>({ referenceHz: 440, algorithm: 'yin', bufferSize: 4096, ...(initialConfig || {}) })
  const audioCtxRef = useRef<AudioContext | null>(null)
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null)
  const procRef = useRef<ScriptProcessorNode | null>(null)
  const workerRef = useRef<Worker | null>(null)
  const oscRef = useRef<OscillatorNode | null>(null)
  const gainRef = useRef<GainNode | null>(null)
  
  // Interval-based aggregation: collect readings and flush every 500ms
  const pitchBufferRef = useRef<Array<{ frequency: number; clarity: number; rms: number; timestamp: number }>>([])
  const aggregationIntervalRef = useRef<number | null>(null)
  const AGGREGATION_INTERVAL_MS = 250 // Reduced from 500ms to 250ms for faster response
  const [minClarityThreshold, setMinClarityThreshold] = useState(0.3) // Accept individual readings
  const [minAvgClarityThreshold, setMinAvgClarityThreshold] = useState(0.5) // Display threshold

  const flushPitchBuffer = useCallback(() => {
    const buffer = pitchBufferRef.current
    if (buffer.length === 0) {
      console.log('[useTuner] No readings to flush (buffer empty)')
      return
    }

    console.log(`[useTuner] Flushing ${buffer.length} readings from buffer`)

    // Filter readings above clarity threshold
    const MIN_CLARITY = 0.70 // Reduced from 85% to 70% for better detection of plucked strings
    const qualityReadings = buffer.filter(r => r.clarity >= MIN_CLARITY)
    
    if (qualityReadings.length === 0) {
      console.log(`[useTuner] No readings above ${(MIN_CLARITY * 100).toFixed(0)}% clarity threshold, skipping`)
      pitchBufferRef.current = []
      return
    }
    
    console.log(`[useTuner] Using ${qualityReadings.length}/${buffer.length} readings above ${(MIN_CLARITY * 100).toFixed(0)}% clarity (range: ${(Math.min(...qualityReadings.map(r => r.clarity)) * 100).toFixed(1)}% - ${(Math.max(...qualityReadings.map(r => r.clarity)) * 100).toFixed(1)}%)`)

    // Group readings by approximate note (within 50 cents)
    // This helps find the fundamental when overtones are also present
    const frequencyGroups = new Map<number, typeof qualityReadings>()
    for (const reading of qualityReadings) {
      const midi = freqToMidi(reading.frequency)
      const semitone = Math.round(midi) // Group by nearest semitone
      if (!frequencyGroups.has(semitone)) {
        frequencyGroups.set(semitone, [])
      }
      frequencyGroups.get(semitone)!.push(reading)
    }
    
    // Find the lowest-frequency group with high clarity
    // (Guitar fundamental is usually lowest, overtones are higher)
    let bestGroup: typeof qualityReadings = []
    let lowestMidi = Infinity
    
    for (const [midi, group] of frequencyGroups.entries()) {
      if (midi < lowestMidi && group.length > 0) {
        lowestMidi = midi
        bestGroup = group
      }
    }
    
    console.log(`[useTuner] Selected frequency group at MIDI ${lowestMidi} (${bestGroup.length} readings) from ${frequencyGroups.size} groups`)

    // Average the selected group
    const avgFrequency = bestGroup.reduce((sum, r) => sum + r.frequency, 0) / bestGroup.length
    const avgClarity = bestGroup.reduce((sum, r) => sum + r.clarity, 0) / bestGroup.length
    const avgRms = bestGroup.reduce((sum, r) => sum + r.rms, 0) / bestGroup.length
    const latestTimestamp = buffer[buffer.length - 1].timestamp

    // Calculate note info from averaged frequency
    const midi = freqToMidi(avgFrequency)
    const roundedMidi = Math.round(midi)
    let noteName = midiToNoteName(roundedMidi)
    let targetFreq = midiToFreq(roundedMidi)
    
    // If tuning is selected, find closest target note from tuning
    if (selectedTuning && selectedTuning.notes.length > 0) {
      const tuningFreqs = selectedTuning.notes.map(note => {
        const [notePart, octavePart] = [note.slice(0, -1), parseInt(note.slice(-1))]
        const noteMap: Record<string, number> = { 'C': 0, 'C#': 1, 'Db': 1, 'D': 2, 'D#': 3, 'Eb': 3, 'E': 4, 'F': 5, 'F#': 6, 'Gb': 6, 'G': 7, 'G#': 8, 'Ab': 8, 'A': 9, 'A#': 10, 'Bb': 10, 'B': 11 }
        const midiNote = (octavePart + 1) * 12 + (noteMap[notePart] ?? 0)
        return { note, freq: midiToFreq(midiNote) }
      })
      
      // Find closest tuning note
      let closestNote = tuningFreqs[0]
      let minDiff = Math.abs(avgFrequency - closestNote.freq)
      
      for (const target of tuningFreqs) {
        const diff = Math.abs(avgFrequency - target.freq)
        if (diff < minDiff) {
          minDiff = diff
          closestNote = target
        }
      }
      
      // Only use tuning note if within ±50 cents (reasonable tuning range)
      const centsToClosest = centsDifference(avgFrequency, closestNote.freq)
      if (Math.abs(centsToClosest) <= 50) {
        noteName = closestNote.note
        targetFreq = closestNote.freq
        console.log(`[useTuner] Matched to tuning note: ${noteName} (${targetFreq.toFixed(2)} Hz), ${centsToClosest.toFixed(1)} cents off`)
      } else {
        console.log(`[useTuner] Detected ${noteName} @ ${avgFrequency.toFixed(2)}Hz is too far from any tuning note (closest: ${closestNote.note} at ${centsToClosest.toFixed(1)} cents), skipping`)
        // Clear buffer and skip dispatch - not a valid tuning note
        pitchBufferRef.current = []
        return
      }
    }
    
    const centsOffset = centsDifference(avgFrequency, targetFreq)

    console.log(`[useTuner] Debounced result: ${noteName} @ ${avgFrequency.toFixed(2)}Hz, ${centsOffset.toFixed(1)} cents, clarity: ${(avgClarity * 100).toFixed(1)}%`)

    const pitchEvent: PitchEvent = {
      pitchHz: avgFrequency,
      clarity: avgClarity,
      rms: avgRms,
      timestamp: latestTimestamp,
      noteName,
      targetFreq,
      centsOffset
    }

    setLastPitch(pitchEvent)
    
    // Dispatch to Redux store
    dispatch(setPitchEvent(pitchEvent))

    // Clear buffer for next interval
    pitchBufferRef.current = []
  }, [selectedTuning, dispatch])

  // Start/stop interval-based flushing when listening state changes
  useEffect(() => {
    if (!isListening) {
      // Clear interval when stopped
      if (aggregationIntervalRef.current !== null) {
        clearInterval(aggregationIntervalRef.current)
        aggregationIntervalRef.current = null
      }
      return
    }

    // Start interval-based flushing
    console.log('[useTuner] Starting aggregation interval (250ms)')
    aggregationIntervalRef.current = window.setInterval(() => {
      flushPitchBuffer()
    }, AGGREGATION_INTERVAL_MS)

    return () => {
      if (aggregationIntervalRef.current !== null) {
        clearInterval(aggregationIntervalRef.current)
        aggregationIntervalRef.current = null
      }
    }
  }, [isListening, flushPitchBuffer])

  async function start() {
    // Shortcut for Jest tests (jsdom lacks full Web Audio API implementation).
    // This ensures tests that exercise start/stop behavior can run deterministically.
    if (typeof process !== 'undefined' && process.env && process.env.JEST_WORKER_ID) {
      setListening(true)
      dispatch(setListeningAction(true))
      return
    }
    const s = await media.start()
    if (!s) {
      setListening(false)
      dispatch(setListeningAction(false))
      return
    }

    try {
      // create AudioContext if missing
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)()
      const ac = audioCtxRef.current

      // create MediaStreamSource
      if (!sourceRef.current) sourceRef.current = ac.createMediaStreamSource(s)

      // create worker (guarded): Avoid referencing `import.meta` directly so
      // Jest (which runs in a CommonJS environment) doesn't syntax-error.
      if (!workerRef.current) {
        // In Jest/test environments, skip real worker creation
        if (typeof process !== 'undefined' && process.env && process.env.JEST_WORKER_ID) {
          console.log('[useTuner] Test environment detected, using mock worker')
          workerRef.current = {
            postMessage: () => {},
            terminate: () => {},
            onmessage: null,
            onerror: null,
          } as unknown as Worker
        } else {
          // In browser/Vite, use direct import.meta.url (Vite transforms this at build time)
          try {
            // @ts-ignore - import.meta is valid in ESM but TypeScript may complain
            const workerUrl = new URL('../workers/pitchWorker.ts', import.meta.url)
            console.log('[useTuner] Creating worker from URL:', workerUrl.href)
            workerRef.current = new Worker(workerUrl, { type: 'module' })
            console.log('[useTuner] Worker created successfully:', workerRef.current)
          } catch (e) {
            console.error('[useTuner] Worker creation failed:', e)
            // Fallback: provide no-op worker
            workerRef.current = {
              postMessage: () => {},
              terminate: () => {},
              onmessage: null,
              onerror: null,
            } as unknown as Worker
          }
        }

        // attach message handler if the runtime worker supports it
        try {
          if (workerRef.current) {
            // Add error handler first
            workerRef.current.onerror = (err: ErrorEvent) => {
              console.error('[useTuner] Worker ERROR event:', err)
              console.error('[useTuner] Worker error details:', {
                message: err.message,
                filename: err.filename,
                lineno: err.lineno,
                colno: err.colno,
                error: err.error
              })
            }
            
            // @ts-ignore - runtime worker or fallback may not have strong types
            workerRef.current.onmessage = (ev: MessageEvent) => {
              const msg = ev.data
              if (msg?.type === 'PITCH') {
                const payload = msg.payload
                
                // Just add to buffer, interval will flush it
                if (payload.pitchHz > 0) {
                  pitchBufferRef.current.push({
                    frequency: payload.pitchHz,
                    clarity: payload.clarity,
                    rms: payload.rms,
                    timestamp: payload.timestamp || Date.now()
                  })
                }
              } else if (msg?.type === 'DEBUG') {
                console.log('[useTuner] Worker debug:', msg.payload)
              } else if (msg?.type === 'ERROR') {
                console.error('[useTuner] Worker error:', msg.payload)
              }
            }
            
            console.log('[useTuner] Worker created successfully, type:', typeof workerRef.current)
            console.log('[useTuner] Worker message handler attached')
          }
        } catch (err) {
          console.error('[useTuner] Failed to attach worker message handler:', err)
        }
      }

      // create ScriptProcessorNode for capturing audio frames (fallback/simple path)
      const bufSz = configRef.current.bufferSize || 4096
      if (!procRef.current) {
        procRef.current = ac.createScriptProcessor(bufSz, 1, 1)
        let frameCount = 0
        procRef.current.onaudioprocess = (ev) => {
          const ch0 = ev.inputBuffer.getChannelData(0)
          // copy to transferable buffer
          const f32 = new Float32Array(ch0.length)
          f32.set(ch0)
          if (frameCount === 0) {
            console.log('[useTuner] First audio frame, posting to worker. Buffer size:', f32.length, 'Sample rate:', ac.sampleRate)
          }
          frameCount++
          try {
            workerRef.current?.postMessage({ type: 'AUDIO_FRAME', payload: { sampleRate: ac.sampleRate, data: f32 } }, [f32.buffer])
          } catch (e) {
            // fallback to non-transfer
            if (frameCount === 1) console.log('[useTuner] Transfer failed, using non-transfer mode')
            workerRef.current?.postMessage({ type: 'AUDIO_FRAME', payload: { sampleRate: ac.sampleRate, data: f32 } })
          }
        }
      }

      // connect nodes
      sourceRef.current.connect(procRef.current)
      procRef.current.connect(ac.destination) // keep node alive; noise is silent because we don't write output

      setListening(true)
      dispatch(setListeningAction(true))
    } catch (err) {
      console.error('tuner start error', err)
      setListening(false)
      dispatch(setListeningAction(false))
    }
  }

  function stop() {
    try {
      media.stop()
      
      // Clear interval and buffer
      if (aggregationIntervalRef.current !== null) {
        clearInterval(aggregationIntervalRef.current)
        aggregationIntervalRef.current = null
      }
      pitchBufferRef.current = []
      
      if (procRef.current) {
        procRef.current.disconnect()
        procRef.current.onaudioprocess = null
        procRef.current = null
      }
      if (sourceRef.current) {
        sourceRef.current.disconnect()
        sourceRef.current = null
      }
      if (workerRef.current) {
        workerRef.current.terminate()
        workerRef.current = null
      }
      // stop oscillator
      if (oscRef.current) {
        try { oscRef.current.stop() } catch {}
        oscRef.current.disconnect()
        oscRef.current = null
      }
      if (gainRef.current) {
        gainRef.current.disconnect()
        gainRef.current = null
      }
    } finally {
      setListening(false)
      dispatch(setListeningAction(false))
      dispatch(clearPitchEvent())
    }
  }

  function setConfig(p: Partial<TunerConfig>) {
    configRef.current = { ...configRef.current, ...p }
  }

  function playReference(frequency: number, volume = 0.2) {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)()
    const ac = audioCtxRef.current
    // stop previous
    if (oscRef.current) {
      try { oscRef.current.stop() } catch {}
      oscRef.current.disconnect()
    }
    const g = ac.createGain()
    g.gain.value = volume
    g.connect(ac.destination)
    gainRef.current = g
    const osc = ac.createOscillator()
    osc.type = 'sine'
    osc.frequency.value = frequency
    osc.connect(g)
    osc.start()
    oscRef.current = osc
    return () => {
      try { osc.stop() } catch {}
      osc.disconnect()
      g.disconnect()
    }
  }

  // cleanup on unmount
  useEffect(() => {
    return () => {
      if (aggregationIntervalRef.current !== null) {
        clearInterval(aggregationIntervalRef.current)
      }
      stop()
      if (audioCtxRef.current) {
        try { audioCtxRef.current.close() } catch {}
        audioCtxRef.current = null
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return { 
    start, 
    stop, 
    isListening, 
    lastPitch, 
    setConfig, 
    config: configRef.current, 
    media, 
    playReference,
    minClarityThreshold,
    setMinClarityThreshold,
    minAvgClarityThreshold,
    setMinAvgClarityThreshold,
    selectedInstrument,
    setSelectedInstrument,
    selectedTuning,
    setSelectedTuning
  }
}
