import React, { useEffect, useState } from 'react'
import { useSelector } from 'react-redux'
import { MinusCircleOutlined, CheckCircleOutlined, ArrowUpOutlined, ArrowDownOutlined } from '@ant-design/icons'
import type { TuningDefinition, PitchEvent } from '../types'
import type { RootState } from '../../../store'
import customPegImg from '../../../img/custom-peg.png'
import { RadialTunerGauge } from './PitchGauge'

interface PegState {
  note: string
  status: 'pending' | 'sharp' | 'flat' | 'tuned'
  lastCents?: number
}

interface TuningPegVisualizerProps {
  tuning: TuningDefinition | null
  lastPitch: PitchEvent | undefined
  isListening: boolean
}

// Utility to compute cents display string
const formatCents = (c?: number) => (c === undefined ? '' : `${c > 0 ? '+' : ''}${c.toFixed(1)}`)

// Strip octave number from note (e.g., "E2" -> "E", "A#3" -> "A#")
const stripOctave = (note: string) => note.replace(/\d+$/, '')

// Convert clockwise order (bottom-left to bottom-right) to screen order (top-to-bottom pairs)
// Input: [E2, A2, D3, G3, B3, E4] (guitar standard, clockwise from bottom-left)
// Output: [D3, G3, A2, B3, E2, E4] (top-to-bottom pairs: left column then right column)
const reorderForDisplay = (notes: string[]): string[] => {
  const half = Math.ceil(notes.length / 2)
  const leftSide = notes.slice(0, half).reverse() // bottom-left to middle, reversed for top-down
  const rightSide = notes.slice(half) // middle to top-right

  const result: string[] = []
  for (let i = 0; i < Math.max(leftSide.length, rightSide.length); i++) {
    if (i < leftSide.length) result.push(leftSide[i])
    if (i < rightSide.length) result.push(rightSide[i])
  }
  return result
}

export const TuningPegVisualizer: React.FC<TuningPegVisualizerProps> = ({
  tuning,
  lastPitch,
  isListening
}) => {
  const [pegStates, setPegStates] = useState<Map<string, PegState>>(new Map())
  const [activeNote, setActiveNote] = useState<string | null>(null)
  
  // Read from Redux - this is the source of truth for pitch data
  const currentPitch = useSelector((state: RootState) => state.tuner.currentPitch)

  // Initialize peg states when tuning changes
  useEffect(() => {
    if (!tuning || tuning.notes.length === 0) {
      setPegStates(new Map())
      return
    }

    const newStates = new Map<string, PegState>()
    tuning.notes.forEach((note) => {
      newStates.set(note, { note, status: 'pending' })
    })
    setPegStates(newStates)
  }, [tuning])

  // Update peg states based on pitch detection from Redux
  useEffect(() => {
    if (!currentPitch || !currentPitch.noteName || !tuning || tuning.notes.length === 0) {
      setActiveNote(null)
      return
    }

    const detectedNote = currentPitch.noteName
    const centsOffset = currentPitch.centsOffset ?? 0

    setPegStates((prev) => {
      const next = new Map(prev)

      if (next.has(detectedNote)) {
        setActiveNote(detectedNote)
        const current = next.get(detectedNote)!
        
        if (Math.abs(centsOffset) < 5) {
          next.set(detectedNote, { ...current, status: 'tuned', lastCents: centsOffset })
        } else if (centsOffset > 0) {
          next.set(detectedNote, { ...current, status: 'sharp', lastCents: centsOffset })
        } else {
          next.set(detectedNote, { ...current, status: 'flat', lastCents: centsOffset })
        }
      } else {
        setActiveNote(null)
      }

      return next
    })
  }, [currentPitch, tuning])

  if (!tuning || tuning.notes.length === 0) {
    return (
      <div style={{ padding: '20px', textAlign: 'center', color: '#999' }}>
        Select an instrument and tuning to see visual progress
      </div>
    )
  }

  // Reorder pegs for display (clockwise instrument order -> screen pairs)
  const reorderedNotes = reorderForDisplay(tuning.notes)
  const displayPegs: PegState[] = reorderedNotes.map((note) => {
    const state = pegStates.get(note)
    return state || { note, status: 'pending' as const }
  })

  // Split pegs into left/right columns (alternate assignment)
  const leftColumn: PegState[] = []
  const rightColumn: PegState[] = []
  displayPegs.forEach((peg, idx) => {
    if (idx % 2 === 0) leftColumn.push(peg)
    else rightColumn.push(peg)
  })

  // Normalize rows length by padding shorter column with undefined
  const rowCount = Math.max(leftColumn.length, rightColumn.length)
  while (leftColumn.length < rowCount) leftColumn.push(undefined as any)
  while (rightColumn.length < rowCount) rightColumn.push(undefined as any)

  // Helpers
  const renderPeg = (peg?: PegState, mirror?: boolean) =>
    peg && (
      <div style={{ 
        position: 'relative', 
        width: 52, 
        height: 52,
        borderRadius: '50%',
        boxShadow: activeNote === peg.note ? '0 0 12px 4px rgba(24, 144, 255, 0.8)' : 'none',
        transition: 'box-shadow 0.2s ease'
      }}>
        <img
          src={customPegImg}
          alt={peg.note}
          style={{ width: 52, height: 'auto', display: 'block', transform: mirror ? 'scaleX(-1)' : 'none' }}
        />
        <span
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            fontSize: 11,
            fontWeight: 'bold',
            color: '#fff',
            textShadow: '0 0 2px #000'
          }}
        >
          {stripOctave(peg.note)}
        </span>
      </div>
    )

  const renderStatus = (peg?: PegState) => {
    if (!peg) return null
    const icon =
      peg.status === 'tuned' ? (
        <CheckCircleOutlined style={{ color: '#52c41a', fontSize: 22 }} />
      ) : peg.status === 'sharp' ? (
        <ArrowUpOutlined style={{ color: '#ff4d4f', fontSize: 22 }} />
      ) : peg.status === 'flat' ? (
        <ArrowDownOutlined style={{ color: '#1890ff', fontSize: 22 }} />
      ) : (
        <MinusCircleOutlined style={{ color: '#faad14', fontSize: 22 }} />
      )
    return <div>{icon}</div>
  }

  return (
    <div style={{ padding: '12px', maxWidth: 640 }}>
      <h4 style={{ marginTop: 0, marginBottom: '12px' }}>Tuning Progress</h4>

      <style>
        {`
        .tuner-peg-layout { display: flex; gap: 16px; align-items: stretch; flex-wrap: wrap; }
        .tuner-peg-col { display: grid; grid-auto-rows: minmax(52px, auto); row-gap: 6px; flex: 0 1 auto; min-width: 150px; }
        .tuner-peg-row { display: grid; grid-template-columns: auto auto auto; align-items: center; column-gap: 8px; }
        .tuner-peg-row .label { font-weight: 600; }
        .tuner-peg-gauge { flex: 0 0 260px; display: flex; justify-content: center; align-items: center; padding: 8px 0; }
        @media (max-width: 719px) {
          .tuner-peg-gauge { flex: 1 1 100%; order: 3; }
        }
        `}
      </style>

      <div className="tuner-peg-layout">
        {/* Left column */}
        <div className="tuner-peg-col">
          {Array.from({ length: rowCount }).map((_, rowIdx) => {
            const leftPeg = leftColumn[rowIdx]
            return (
              <div className="tuner-peg-row" key={`left-${rowIdx}`}>
                <div className="label" style={{ textAlign: 'right' }}>{leftPeg ? stripOctave(leftPeg.note) : ''}</div>
                {renderPeg(leftPeg, true)}
                {renderStatus(leftPeg)}
              </div>
            )
          })}
        </div>

        {/* Gauge: centered between columns on wide screens, stacked below on narrow */}
        <div className="tuner-peg-gauge">
          <RadialTunerGauge defaultTargetHz={440} />
        </div>

        {/* Right column */}
        <div className="tuner-peg-col">
          {Array.from({ length: rowCount }).map((_, rowIdx) => {
            const rightPeg = rightColumn[rowIdx]
            return (
              <div className="tuner-peg-row" key={`right-${rowIdx}`}>
                {renderStatus(rightPeg)}
                {renderPeg(rightPeg, false)}
                <div className="label">{rightPeg ? stripOctave(rightPeg.note) : ''}</div>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}
