export interface MediaStreamHandle {
  stream: MediaStream | null
  deviceId?: string
}

export interface TunerConfig {
  referenceHz: number
  algorithm: 'yin' | 'autocorr' | 'fft'
  bufferSize: number
}

export interface PitchEvent {
  pitchHz: number
  clarity: number
  rms: number
  timestamp: number
  noteName?: string
  targetFreq?: number
  centsOffset?: number
}

export interface TuningDefinition {
  name: string
  notes: string[] // e.g., ['E2', 'A2', 'D3', 'G3', 'B3', 'E4']
}

export interface InstrumentDefinition {
  name: string
  tunings: TuningDefinition[]
}

