import React from "react";
import { useSelector } from 'react-redux';
import GaugeComponent from "react-gauge-component";
import type { RootState } from '../../../store';

interface RadialTunerGaugeProps {
  defaultTargetHz?: number; // Optional default when no pitch is detected
}

export const RadialTunerGauge: React.FC<RadialTunerGaugeProps> = ({
  defaultTargetHz = 440
}) => {
  // Get pitch data from Redux
  const currentPitch = useSelector((state: RootState) => state.tuner.currentPitch);
  
  // Use Redux pitch data or fall back to defaults
  const freqHz = currentPitch?.pitchHz ?? defaultTargetHz;
  const targetHz = currentPitch?.targetFreq ?? defaultTargetHz;
  
  // Debug logging
  React.useEffect(() => {
    console.log('[PitchGauge] Redux update:', { 
      hasPitch: !!currentPitch, 
      freqHz, 
      targetHz,
      noteName: currentPitch?.noteName,
      centsOffset: currentPitch?.centsOffset 
    });
  }, [currentPitch, freqHz, targetHz]);
  
  // Use the pre-calculated cents offset from Redux (already computed by useTuner)
  const cents = currentPitch?.centsOffset ?? 0;

  // Clamp display range for visual stability
  const clampedCents = Math.max(-50, Math.min(50, cents));

  // Map -50..50 → 0..100 for the gauge
  const gaugeValue = clampedCents + 50;

  // Compute Hz labels around the center
  // ±5¢ and ±15¢ reference points — this is very readable to musicians
  const hzPlus5   = targetHz * Math.pow(2, 5 / 1200);
  const hzPlus15  = targetHz * Math.pow(2, 15 / 1200);
  const hz5CentDifference = hzPlus5 - targetHz;
  const hz15CentDifference = hzPlus15 - targetHz;

  // Round for display
  const fmt = (n: number) => n.toFixed(2);

  return (
    <div style={{ width: "100%", maxWidth: 360, margin: "0 auto" }}>
      <GaugeComponent
        key={`gauge-${targetHz}-${freqHz}`}
        type="radial"
        value={gaugeValue}
        minValue={0}
        maxValue={100}
        arc={{
          width: 0.28,
          padding: 0.03,
          colorArray: [
            "#d32f2f", // Very flat
            "#f57c00", // Slightly flat
            "#4caf50", // In tune
            "#f57c00", // Slightly sharp
            "#d32f2f"  // Very sharp
          ],
          subArcs: [
            { limit: 20 },  // 0–20   => very flat
            { limit: 40 },  // 20–40  => slightly flat
            { limit: 60 },  // 40–60  => in tune
            { limit: 80 },  // 60–80  => slightly sharp
            { limit: 100 }  // 80–100 => very sharp
          ],
        }}
        pointer={{
          elastic: true,
          animationDuration: 160
        }}
        labels={{
          valueLabel: {
            formatTextValue: () => `${freqHz.toFixed(2)} Hz`
          },
          tickLabels: {
            type: "outer",
            ticks: [

              { value: 0, valueConfig: { formatTextValue: () => 'very flat' } },
              { value: 20, valueConfig: { formatTextValue: () => `-${fmt(hz15CentDifference)}Hz` } },
              { value: 40, valueConfig: { formatTextValue: () =>  `-${fmt(hz5CentDifference)}Hz` } },
              { value: 50, valueConfig: { formatTextValue: () => `${fmt(targetHz)}Hz` } },
              { value: 60, valueConfig: { formatTextValue: () =>  `+${fmt(hz5CentDifference)}Hz` } },
              { value: 80, valueConfig: { formatTextValue: () =>  `+${fmt(hz15CentDifference)}Hz` } },
              { value: 100, valueConfig: { formatTextValue: () =>'very sharp' } }
            ]
          }
        }}
      />
    </div>
  );
};