/**
 * Minimal pitch utilities: midi/frequency/note conversions and cents diff
 */
export function freqToMidi(frequency: number): number {
  return 69 + 12 * Math.log2(frequency / 440)
}

export function midiToFreq(midi: number): number {
  return 440 * Math.pow(2, (midi - 69) / 12)
}

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']

export function midiToNoteName(midi: number): string {
  const n = Math.round(midi)
  const name = NOTE_NAMES[(n + 120) % 12]
  const octave = Math.floor(n / 12) - 1
  return `${name}${octave}`
}

export function freqToNoteName(freq: number) {
  const midi = freqToMidi(freq)
  return midiToNoteName(midi)
}

export function centsDifference(freq: number, refFreq: number): number {
  return 1200 * Math.log2(freq / refFreq)
}
