export type MediaState = 'idle' | 'requesting' | 'active' | 'error'

export interface UseMediaOptions {
  audio?: boolean
  video?: boolean | { facingMode?: 'user' | 'environment'; width?: number; height?: number }
}

export interface MediaHandle {
  stream: MediaStream | null
  state: MediaState
  error: Error | null
  start: () => Promise<MediaStream | null>
  stop: () => void
  selectDevice?: (deviceId: string) => Promise<void>
  listDevices: () => Promise<MediaDeviceInfo[]>
  captureFrame?: (videoEl: HTMLVideoElement) => Promise<Blob | null>
}

import { useEffect, useRef, useState } from 'react'

export function useMedia(opts: UseMediaOptions = {}): MediaHandle {
  const { audio = false, video = false } = opts
  const [stream, setStream] = useState<MediaStream | null>(null)
  const [state, setState] = useState<MediaState>('idle')
  const [error, setError] = useState<Error | null>(null)
  const optsRef = useRef(opts)

  useEffect(() => {
    optsRef.current = opts
  }, [opts])

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(t => t.stop())
      }
    }
  }, [stream])

  function buildConstraints(deviceId?: string): MediaStreamConstraints {
    const c: MediaStreamConstraints = {}
    if (audio) c.audio = deviceId ? { deviceId: { exact: deviceId } } : true
    if (video) {
      if (typeof video === 'boolean') c.video = deviceId ? { deviceId: { exact: deviceId } } : true
      else {
        const v: any = { facingMode: video.facingMode || 'environment' }
        if (video.width) v.width = { ideal: video.width }
        if (video.height) v.height = { ideal: video.height }
        c.video = deviceId ? { deviceId: { exact: deviceId } } : v
      }
    }
    return c
  }

  async function start(): Promise<MediaStream | null> {
    setState('requesting')
    try {
      const constraints = buildConstraints()
      const s = await navigator.mediaDevices.getUserMedia(constraints)
      setStream(s)
      setState('active')
      setError(null)
      return s
    } catch (err) {
      const e = err as Error
      setError(e)
      setState('error')
      setStream(null)
      return null
    }
  }

  function stop() {
    if (stream) {
      stream.getTracks().forEach(t => t.stop())
      setStream(null)
    }
    setState('idle')
  }

  async function selectDevice(deviceId: string) {
    if (!deviceId) return
    stop()
    try {
      const constraints = buildConstraints(deviceId)
      const s = await navigator.mediaDevices.getUserMedia(constraints)
      setStream(s)
      setState('active')
      setError(null)
    } catch (err) {
      const e = err as Error
      setError(e)
      setState('error')
    }
  }

  async function listDevices(): Promise<MediaDeviceInfo[]> {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices()
      return devices
    } catch (_) {
      return []
    }
  }

  async function captureFrame(videoEl: HTMLVideoElement): Promise<Blob | null> {
    if (!videoEl || videoEl.readyState < 2) return null
    try {
      const w = videoEl.videoWidth
      const h = videoEl.videoHeight
      const canvas = document.createElement('canvas')
      canvas.width = w
      canvas.height = h
      const ctx = canvas.getContext('2d')!
      ctx.drawImage(videoEl, 0, 0, w, h)
      return await new Promise<Blob | null>((resolve) => canvas.toBlob(b => resolve(b), 'image/jpeg'))
    } catch (err) {
      return null
    }
  }

  return { stream, state, error, start, stop, selectDevice, listDevices, captureFrame }
}
